Proceso SumaDeVector
    Dimension numeros[5] Como Entero;
    Definir i Como Entero;
    Definir total Como Entero;
    Para i <- 0 Hasta 4 Hacer
        Leer numeros[i];
    FinPara
    total <- 0;
    Para i <- 0 Hasta 4 Hacer
        total <- total + numeros[i];
    FinPara
    Escribir total;
FinProceso
